// Decodes the real illustration assets (assets/art/**/*.webp) from their
// committed base64 sources (same path + ".b64"). The .webp files are build
// artifacts: they are regenerated by this script on postinstall and in the
// Vercel build command, so a fresh clone only needs `npm install`.
import { readdirSync, readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', 'assets', 'art');
function walk(dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = join(dir, e.name);
    return e.isDirectory() ? walk(p) : e.name.endsWith('.webp.b64') ? [p] : [];
  });
}
let decoded = 0;
for (const b64Path of walk(root)) {
  const out = b64Path.slice(0, -4);
  if (existsSync(out) && statSync(out).mtimeMs >= statSync(b64Path).mtimeMs) continue;
  writeFileSync(out, Buffer.from(readFileSync(b64Path, 'utf8').trim(), 'base64'));
  decoded++;
}
console.log(`decode-art: ${decoded} file(s) decoded`);
